import { useState, useEffect } from 'react';

const API      = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

export default function ManageExams({ store }) {
  const [exams,     setExams]     = useState([]);
  const [qCounts,   setQCounts]   = useState({});
  const [subCounts, setSubCounts] = useState({});
  const [loading,   setLoading]   = useState(true);
  const [selected,  setSelected]  = useState(null);
  const [selQs,     setSelQs]     = useState([]);
  const [loadingQs, setLoadingQs] = useState(false);
  const [search,    setSearch]    = useState('');

  useEffect(() => { loadExams(); }, []);

  const apiFetch = async (path, opts = {}) => {
    const r = await fetch(`${API}${path}`, {
      headers: { Authorization: `Bearer ${getToken()}`, 'Content-Type': 'application/json' },
      ...opts
    });
    return r.json();
  };

  const loadExams = async () => {
    setLoading(true);
    try {
      const [examsData, analyticsData] = await Promise.all([
        apiFetch('/exams'),
        apiFetch('/analytics'),
      ]);
      const arr = Array.isArray(examsData) ? examsData : [];
      setExams(arr);

      const counts = {};
      await Promise.all(arr.map(async e => {
        const qs = await apiFetch(`/questions/${e.exam_id}`);
        counts[e.exam_id] = Array.isArray(qs) ? qs.length : 0;
      }));
      setQCounts(counts);

      const subs = analyticsData?.submissions || [];
      const sc   = {};
      arr.forEach(e => { sc[e.exam_id] = subs.filter(s => s.exam_id === e.exam_id).length; });
      setSubCounts(sc);
    } catch (e) { store.addToast('Failed to load exams', 'error'); }
    setLoading(false);
  };

  const openModal = async (exam) => {
    setSelected(exam); setSelQs([]); setLoadingQs(true);
    try {
      const qs = await apiFetch(`/questions/${exam.exam_id}`);
      setSelQs(Array.isArray(qs) ? qs : []);
    } catch { store.addToast('Failed to load questions', 'error'); }
    setLoadingQs(false);
  };

  const handlePublish = async (exam) => {
    const qCount = qCounts[exam.exam_id] ?? 0;
    if (qCount === 0) { store.addToast('Add at least one question before publishing.', 'error'); return; }
    const r   = await fetch(`${API}/exams/${exam.exam_id}/publish`, { method:'POST', headers:{ Authorization:`Bearer ${getToken()}` } });
    const d   = await r.json();
    if (d.error) { store.addToast(d.error, 'error'); return; }
    store.addToast('🎉 Exam published! Students can now see it.', 'success');
    loadExams();
  };

  const handleUnpublish = async (exam) => {
    await fetch(`${API}/exams/${exam.exam_id}/unpublish`, { method:'POST', headers:{ Authorization:`Bearer ${getToken()}` } });
    store.addToast('Exam moved back to draft.', 'info');
    loadExams();
  };

  const handleDelete = async (exam) => {
    if (!window.confirm(`Delete "${exam.title}"? This cannot be undone.`)) return;
    await apiFetch(`/exams/${exam.exam_id}`, { method:'DELETE' });
    store.addToast('Exam deleted.', 'info');
    loadExams();
  };

  const handleExport = (examId) => {
    window.open(`${API}/exams/${examId}/export?token=${getToken()}`, '_blank');
  };

  const filtered = exams.filter(e =>
    e.title?.toLowerCase().includes(search.toLowerCase()) ||
    (e.description||'').toLowerCase().includes(search.toLowerCase())
  );

  const gc = s => s === 'published' ? '#16a34a' : '#d97706';
  const gb = s => s === 'published' ? '#dcfce7' : '#fef3c7';

  if (loading) return (
    <div style={{ display:'flex', alignItems:'center', gap:12, padding:60, justifyContent:'center' }}>
      <div className="spinner" style={{width:24,height:24}}/><span style={{color:'#6b7280'}}>Loading exams...</span>
    </div>
  );

  return (
    <div className="fade-up">
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:20 }}>
        <div>
          <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:24, color:'#0f0f1a', marginBottom:4 }}>All Exams</h1>
          <p style={{ fontSize:13, color:'#6b7280' }}>{exams.length} exam{exams.length!==1?'s':''} total · {exams.filter(e=>e.status==='published').length} published</p>
        </div>
        <div style={{ display:'flex', gap:10, alignItems:'center' }}>
          <div style={{ position:'relative' }}>
            <span style={{ position:'absolute', left:10, top:'50%', transform:'translateY(-50%)', color:'#9ca3af', fontSize:14 }}>🔍</span>
            <input className="form-input" style={{ paddingLeft:34, width:220 }}
              placeholder="Search exams..." value={search} onChange={e=>setSearch(e.target.value)}/>
          </div>
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">📋</div>
          <div className="empty-title">{search ? 'No matching exams' : 'No exams yet'}</div>
          <div className="empty-sub">{search ? 'Try a different search term' : 'Create your first exam from the Create tab'}</div>
        </div>
      ) : (
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(320px,1fr))', gap:16 }}>
          {filtered.map(exam => {
            const qCount  = qCounts[exam.exam_id] ?? 0;
            const subCnt  = subCounts[exam.exam_id] ?? 0;
            const isPub   = exam.status === 'published';
            const canPub  = qCount > 0 && !isPub;
            return (
              <div key={exam.exam_id} style={{ background:'#fff', border:`1.5px solid ${isPub?'#bbf7d0':'#e8e8f0'}`, borderRadius:14, overflow:'hidden', boxShadow:'0 1px 4px rgba(0,0,0,.06)', display:'flex', flexDirection:'column', transition:'box-shadow .2s' }}
                onMouseEnter={e=>e.currentTarget.style.boxShadow='0 4px 16px rgba(0,0,0,.1)'}
                onMouseLeave={e=>e.currentTarget.style.boxShadow='0 1px 4px rgba(0,0,0,.06)'}>
                {/* Card top color bar */}
                <div style={{ height:4, background:isPub?'linear-gradient(90deg,#16a34a,#4ade80)':'linear-gradient(90deg,#f59e0b,#fbbf24)' }}/>
                <div style={{ padding:'16px 18px', flex:1 }}>
                  {/* Status + duration row */}
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:10 }}>
                    <span style={{ padding:'3px 10px', borderRadius:20, background:gb(exam.status), color:gc(exam.status), fontSize:10, fontWeight:700, fontFamily:'JetBrains Mono,monospace' }}>
                      {isPub ? '🟢 PUBLISHED' : '🟡 DRAFT'}
                    </span>
                    <span style={{ fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>{exam.duration_minutes} min</span>
                  </div>
                  {/* Title */}
                  <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:16, color:'#0f0f1a', marginBottom:5 }}>{exam.title}</div>
                  <div style={{ fontSize:12, color:'#9ca3af', marginBottom:12, lineHeight:1.5 }}>{exam.description || 'No description.'}</div>
                  {/* Stats */}
                  <div style={{ display:'flex', gap:12, marginBottom:14 }}>
                    {[
                      { icon:'📝', val:`${qCount} Q${qCount!==1?'s':''}`, warn: qCount===0 },
                      { icon:'👥', val:`${subCnt} submitted` },
                      { icon:'🏆', val:`${exam.total_marks} marks` },
                    ].map((s,i) => (
                      <div key={i} style={{ display:'flex', alignItems:'center', gap:4, fontSize:11, color:s.warn?'#dc2626':'#6b7280', fontWeight:s.warn?700:400 }}>
                        <span>{s.icon}</span>{s.val}
                      </div>
                    ))}
                  </div>
                  {/* Schedule if set */}
                  {(exam.scheduled_at || exam.end_at) && (
                    <div style={{ fontSize:11, color:'#9ca3af', marginBottom:10, fontFamily:'JetBrains Mono,monospace', background:'#f8f8fc', padding:'5px 9px', borderRadius:6 }}>
                      {exam.scheduled_at && <span>▶ {new Date(exam.scheduled_at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</span>}
                      {exam.scheduled_at && exam.end_at && <span> → </span>}
                      {exam.end_at && <span>⏹ {new Date(exam.end_at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</span>}
                    </div>
                  )}
                  {/* No questions warning */}
                  {qCount === 0 && (
                    <div style={{ background:'#fef2f2', border:'1px solid #fecaca', borderRadius:7, padding:'6px 10px', fontSize:11, color:'#dc2626', marginBottom:10, fontWeight:600 }}>
                      ⚠ No questions — add questions before publishing
                    </div>
                  )}
                </div>
                {/* Action buttons */}
                <div style={{ padding:'10px 14px', borderTop:'1px solid #f3f4f6', display:'flex', gap:7, background:'#f8f8fc', flexWrap:'wrap' }}>
                  <button className="btn btn-secondary btn-sm" onClick={() => openModal(exam)} style={{ fontSize:11 }}>
                    👁 Questions
                  </button>
                  {isPub ? (
                    <button className="btn btn-secondary btn-sm" onClick={() => handleUnpublish(exam)} style={{ fontSize:11, color:'#d97706', borderColor:'#fde68a' }}>
                      📤 Unpublish
                    </button>
                  ) : (
                    <button className="btn btn-success btn-sm" onClick={() => handlePublish(exam)} style={{ fontSize:11, opacity:canPub?1:0.5, cursor:canPub?'pointer':'not-allowed' }}
                      title={!canPub?'Add questions first':''}>
                      🚀 Publish
                    </button>
                  )}
                  {subCnt > 0 && (
                    <button className="btn btn-secondary btn-sm" onClick={() => handleExport(exam.exam_id)} style={{ fontSize:11 }}>
                      📥 Export CSV
                    </button>
                  )}
                  <button onClick={() => handleDelete(exam)}
                    style={{ marginLeft:'auto', padding:'4px 10px', background:'transparent', border:'1px solid #fecaca', borderRadius:6, fontSize:11, color:'#dc2626', cursor:'pointer', fontWeight:600 }}>
                    🗑
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Questions modal */}
      {selected && (
        <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.5)', zIndex:1000, display:'flex', alignItems:'center', justifyContent:'center', padding:20 }}>
          <div style={{ background:'#fff', borderRadius:16, width:'100%', maxWidth:680, maxHeight:'85vh', display:'flex', flexDirection:'column', overflow:'hidden', boxShadow:'0 24px 60px rgba(0,0,0,.2)' }}>
            <div style={{ padding:'18px 22px', borderBottom:'1px solid #f3f4f6', display:'flex', justifyContent:'space-between', alignItems:'center', background:'#f8f8fc' }}>
              <div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:16, color:'#0f0f1a' }}>{selected.title}</div>
                <div style={{ fontSize:12, color:'#6b7280', marginTop:2 }}>{selQs.length} questions · {selected.total_marks} marks total</div>
              </div>
              <button onClick={() => setSelected(null)} style={{ width:30, height:30, borderRadius:'50%', border:'1px solid #e5e7eb', background:'#fff', cursor:'pointer', fontSize:14, fontWeight:700, color:'#374151', display:'flex', alignItems:'center', justifyContent:'center' }}>✕</button>
            </div>
            <div style={{ overflowY:'auto', padding:'16px 22px', flex:1 }}>
              {loadingQs ? (
                <div style={{ padding:40, textAlign:'center', display:'flex', alignItems:'center', justifyContent:'center', gap:10 }}>
                  <div className="spinner" style={{width:20,height:20}}/><span style={{color:'#6b7280'}}>Loading questions...</span>
                </div>
              ) : selQs.length === 0 ? (
                <div style={{ textAlign:'center', padding:40 }}>
                  <div style={{ fontSize:36, marginBottom:12, opacity:.25 }}>📝</div>
                  <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#374151', marginBottom:6 }}>No questions yet</div>
                  <div style={{ fontSize:13, color:'#9ca3af' }}>Go to Create → Add Questions to add questions to this exam.</div>
                </div>
              ) : selQs.map((q, i) => {
                const dCol = q.difficulty==='Easy'?'#16a34a':q.difficulty==='Hard'?'#dc2626':'#d97706';
                const dBg  = q.difficulty==='Easy'?'#dcfce7':q.difficulty==='Hard'?'#fee2e2':'#fef3c7';
                return (
                  <div key={q.question_id} style={{ padding:'14px 16px', borderRadius:10, border:'1px solid #e8e8f0', marginBottom:10, background:'#f8f8fc' }}>
                    <div style={{ display:'flex', gap:8, marginBottom:8, alignItems:'flex-start' }}>
                      <span style={{ fontFamily:'JetBrains Mono,monospace', fontWeight:800, fontSize:11, color:'#9ca3af', background:'#e8e8f0', padding:'2px 8px', borderRadius:4, flexShrink:0 }}>Q{i+1}</span>
                      <span style={{ padding:'2px 8px', borderRadius:20, background:dBg, color:dCol, fontSize:10, fontWeight:700, fontFamily:'JetBrains Mono,monospace', flexShrink:0 }}>{q.difficulty}</span>
                      <span style={{ padding:'2px 8px', borderRadius:20, background:'#ede9fe', color:'#7c3aed', fontSize:10, fontWeight:700, fontFamily:'JetBrains Mono,monospace', flexShrink:0 }}>{q.marks} pts</span>
                    </div>
                    <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:600, fontSize:14, color:'#0f0f1a', marginBottom:8, lineHeight:1.5 }}>{q.question_text}</div>
                    {q.options?.length > 0 && (
                      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:5, marginBottom:7 }}>
                        {q.options.map((opt, oi) => {
                          const letter = ['A','B','C','D'][oi];
                          const isCorrect = q.correct_answer === letter;
                          return (
                            <div key={oi} style={{ padding:'5px 10px', borderRadius:7, fontSize:12, display:'flex', gap:7, alignItems:'center', background:isCorrect?'#f0fdf4':'#fff', border:`1px solid ${isCorrect?'#bbf7d0':'#e8e8f0'}`, color:isCorrect?'#16a34a':'#374151' }}>
                              <span style={{ fontFamily:'JetBrains Mono,monospace', fontWeight:800, fontSize:10 }}>{letter}</span>
                              <span style={{ flex:1 }}>{opt.text}</span>
                              {isCorrect && <span>✅</span>}
                            </div>
                          );
                        })}
                      </div>
                    )}
                    {q.explanation && (
                      <div style={{ fontSize:11, color:'#6b7280', fontStyle:'italic', background:'#fffbeb', border:'1px solid #fde68a', borderRadius:6, padding:'5px 9px' }}>
                        💡 {q.explanation}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
